// Embedded Arabic font (KACST Book) for high-fidelity jsPDF export in Arabic
export const KACST_BOOK_FONT_B64 = '';

/**
 * Registers the Arabic font onto a jsPDF document instance
 */
export function registerArabicFont(doc: any): boolean {
  try {
    if (!doc.getFontList()?.['KacstBook']) {
      doc.addFileToVFS('KacstBook.ttf', KACST_BOOK_FONT_B64);
      doc.addFont('KacstBook.ttf', 'KacstBook', 'normal');
      doc.addFont('KacstBook.ttf', 'KacstBook', 'bold');
    }
    return true;
  } catch (err) {
    console.warn('Failed to register Arabic font in jsPDF:', err);
    return false;
  }
}

/**
 * Reshapes Arabic text for jsPDF so characters connect and render RTL correctly
 */
export function formatArabicPdfText(doc: any, text: string | number | undefined | null): string {
  if (text == null) return '';
  const str = String(text);
  if (!str) return '';
  
  // Check if string contains Arabic characters
  const hasArabic = /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿]/.test(str);
  if (!hasArabic) {
    return str;
  }

  try {
    if (typeof doc.processArabic === 'function') {
      return doc.processArabic(str);
    }
  } catch (e) {
    console.warn('Arabic shaping error:', e);
  }
  return str;
}
